BEGIN;

SET LOCAL search_path = public;

ALTER TABLE public.professor_review ENABLE ROW LEVEL SECURITY;

ALTER TABLE public.professor_review_course ENABLE ROW LEVEL SECURITY;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (597::BIGINT, 'El profe es una excelenye personas y muy amable, siempre esta dispuesto a ayudar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-07-17T00:00:00+00:00'::TIMESTAMPTZ, '606955d780c54a2b4582afe31b43cb21f1620e6f11593ff554a0324226e2f8e2'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'El profesor es excelente. Ayuda mucho y es muy agradable. No le hace honor la calificación que tiene en este sitio. Para mí es un 9/10.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Brinda apoyo']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'a8211e821ffc506bc3958b7882c1ebc990891e7db862258b7e43c8e928bf0474'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Tareas todas las semanas que califica duro al igual que los exámenes. Después de cada clase hay que subir el trabajo. Como persona es demasiado bueno, pero como profe no explica muy bien y casi no se le entiende lo teórico.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, '2ec9e818875a9d2bf757345d7742485b02d4cb4c4d344dbda1cf5dc216378518'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases largas']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '90fa755397cf07d0310cfe36a5b10dee05f1756255652103713983a65d561f26'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Es una excelente persona, sin duda tiende a ser muy comprensivo. Le gusta la puntualidad y el orden. La dificultad se debe al tipo de curso, pero el lo hace bastante llevadero. Deja bastante tarea pero es para practicar.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-07-31T00:00:00+00:00'::TIMESTAMPTZ, '8851cd89ab547c1963d3eed297dbac08b0fcd52d582689d2c133de7db9a16ee2'::TEXT, ARRAY[1179, 4811]::BIGINT[]),
    (597::BIGINT, 'El curso quita bastante tiempo y al profe le cuesta explicar. Es puro AutoCAD y solo una pequeña parte a mano. El curso es difícil si te cuesta la ubicación espacial. Es exigente con las tareas y exámenes. Lo que más me disgustó esque tiene preferencias y si no le agradas cuesta que te ayude.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2019-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'ddd5259b9f18fbbd02b9906ea76d1bc03586a027f2bfce158b307e5ab7c33863'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Preste mucha atención al inicio de las clases, al profe le cuesta explicar. El curso es fácil, el profe ayuda bastante, siempre traté de entender las cosas que hizo mal para que llegue preparad@ a los exámenes. La forma en que califica no es clara, pero no tenga miedo a preguntarle.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Brinda apoyo']::TEXT[], '2019-11-27T00:00:00+00:00'::TIMESTAMPTZ, '1f4446de1a6bb5c1fd21768177712cb97d1e6a603080d5def6591faff613f7d2'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Le gusta que vayan a consulta y ayuda.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-23T00:00:00+00:00'::TIMESTAMPTZ, '906df113b4b1a1d00ccfe65747db0b27e7494f7c1bfef48a161fcdcde2013673'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'El profe le gusta que vayan a consulta y en consulta realmente explica bastante bien. Le gusta que la gente participe en clase y deja tareas todas las semanas, lo cual es bueno, porque lo mantiene a uno practicando.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2019-08-23T00:00:00+00:00'::TIMESTAMPTZ, 'c568a41b085803ca1885ddc5267990653b65b835c58bf770d61cb2e013bee7c2'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'El profe es muy buena persona, le gusta que la gente vaya a consulta y en consulta explica bastante bien.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2019-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'ec4d2a204202dc6b6107106d53ae2bbc0c64f91eb70847b367d49ddfc3cd7258'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Si muestra interés en la clase el le ayuda bastante, sientes al frente y particepe en clase y todo irá bien.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '0abd7e96fc5da99f257051b111c5a403003d5ec57e9e18b141964eda6680a956'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'De no ser porque el curso es fácil, a nadie le iría bien. No explica con mucha claridad y califica sin dar la rubrica antes. Su humor cambia demasiado de un día para otro, solo lo hace feliz que pierda saprissa'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, '74eb5028354c46eda1dbd7f55838cb98e728e540242c6fba27df0424738d149d'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Deja un montón de tareas y las califica duro. Pero los exámenes son muy fáciles porque uno ya hizo un montón de ejercicios en las tareas. Explica la parte de proyecciones muy mal, pero si estudia del folleto que le da se entiende. Lo mejor es que el examen es a cuaderno abierto. Se pasa fácil'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-30T00:00:00+00:00'::TIMESTAMPTZ, '8666baf2f30f448d2a91a39b11b8fd7b68bd6714e1741afcd6d5a655f85a6208'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Al mae le gusta que uno vaya a consulta, es un poco grosero pero no se lo tome personal. El mae califica como le da la gana. No es mal profe, el explica las reglas del juego a principio de semestre, póngale al principio'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, '908a88c39c5103c49da715994d00360c4b5cd4e1f787a6ba98f45901764c388f'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'El profe es muy extraño, tiene cambios de humor repentinos, y penaliza las tareas y/o exámenes por cualquier cosa, califica demasiado duro y pretende que todos los estudiantes aprenden igual. Es de los profes que no regalan absolutamente PERO NADA.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '1972d3b06dbf1e37c0d28cf2cceeb46c6a8ffe1e4facf124310f959ec2f40904'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'es el único que da ese curso, los avances quitan tiempo. La asistencia es muy importante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '04b6f727873d97dc75b6d1bd9c22452e451b2e00c4c10f42b0a78fd7dc701e6d'::TEXT, ARRAY[1216]::BIGINT[]),
    (597::BIGINT, 'El profe es bueno porque medio sabe la materia, pero es un poco irresponsable con la calificación de los trabajos/examenes, a principio de semestre dice que reconoce algo si uno le envía el trabajo hecho en el semestre pero al final no lo hace.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '60'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, '79e6b23ded1cc6b6368638dcc4c6a515cb77512475d040c5376b06717cdd7516'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Es un profe súper raro, a veces ando hecho un amor y a veces anda todo amargado, como que revuelve aspectos personales con el trabajo. Muchos temas en autocad no los maneja, pero en la parte de interpretación es bastante bueno. Pero si puede matricular con otro profe mejor.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'ea89abee8c8907ce20a50b5fd4538383fbe3b34e62be2ec02092582992b8f69b'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'El profe no es del todo mal pero tiene muchas cosas en contra. No domina muy bien la materia, se enreda mucho y califica muy rudo para lo poco que enseña. Lo bueno es que deja tarea todas las semanas. Es un toque cambiante de humor, pero cae bien.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '3781436216df4720efca2cc0e9cc7d2a43d4f45372ec88828a01b2d84af9606b'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Es buen profesor, se preocupa por que uno aprenda y ayuda siempre que unolo necesite, además hace todo lo posible por que uno no pierda el curso'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '3e2475c1e75d7961f4347387133f8ee40c1886d98840f0929d6fdacc59cce9ae'::TEXT, ARRAY[1216, 1241]::BIGINT[]),
    (597::BIGINT, 'es muy buen profe. tareas cada semana parecidas al examen. en ciertos temas se enreda mucho y ni él se entiende. si les dice que no entra algo en el examen es lo primero que va a entrar'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'fd87f81e2cb78e5368dabf3df8df330c687887052a0b599a07d19fb28561c98d'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Excelente profe, deja tareas todas las semanas (Cortas) que le ayudan a uno a no descuidar el curso y comprender mejor los contenidos, en consulta es una teja siempre se preocupa porque uno entienda. En clase a veces se traba pero es porque ciertos temas son complejos, excelente persona, recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'd1159eaec58d1781b01d9400d429bcdfd1bb41adba154cbc5a8fb5adc3d41bd8'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'A veces anda de malas, a veces anda de buenas. Enreda un poco al explicar pero en la práctica aclara todo. Deja tareas fáciles todas las semanas y los exámenes son un poco difíciles pero es un muy buen profe. Se preocupa por que uno aprenda'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'e23a46076677922e60e6f885d77ed5cfd8662dcca25e8370deba2a7402430755'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'El profe trata de explicar lo mejor que puede, es importante tomar apuntes y si no se entiende lo mejor es ir a consulta, de manera personal explica muy bien'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-28T00:00:00+00:00'::TIMESTAMPTZ, '960befb192bd30d0d3de60b8660d0b03bb664e4eea02f207c62d161f32a92621'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'El profe aveces se "traba" explicando, pero la materia es complicada a veces. Sin embargo el profe es un éxito, se esfuerza porque el estudiante entienda, y en consulta es muy comprensivo y explica muy bien, a parte califica justo. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'db9c154b8be56ba597450fdbe7f0b84f87b033470409584ebecc0978e3911e1d'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Buen profe... explica bien lo que quiere que el estudiante haga... atiende dudas... recomendado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'd8366f0685fb5f956082762acf3b67283221d94224f4ee10603274a676295113'::TEXT, ARRAY[3340, 3341, 612, 3344, 3345, 2853]::BIGINT[]),
    (597::BIGINT, 'Buen profe. Deja tarea casi todas las semanas y atiende cualquier duda de la tarea en consulta, por lo que se aprende bastante. Hacer las tareas es suficiente para salir bien en los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-23T00:00:00+00:00'::TIMESTAMPTZ, '4a2e5cbaa9b3ad6e68d5d4822c7a9fcd446b1faaacdf8dca15f160723613401e'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'El mae de vez en cuando anda muy amargado y le grita a uno.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'e75479aef4f1ab76651dae56f911f0b93b8151e58bfaaaba331e2dc6b6e74ea0'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Es demasiado tuanis! Deja tareas todas las semanas pero no muy pesadas, explica bien y califica super suave. Buen profe para aprender y pasar dibujo bien'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'aefd544fd509099c234ae0ff5c8f6155d2239310d432dac3a4c4da2b0b4d3cb9'::TEXT, ARRAY[3340, 3341, 612, 3344, 3345, 2853]::BIGINT[]),
    (597::BIGINT, 'Hágase un favor y no meta con el, es bastante confuso explicando algunos temas complejos del curso, siempre dice que "hay que fumarsela" para entender, califica exageradamente rudo y como le da la gana los trabajos, se enoja si hay dudas, te puede bajar 20 puntos de un solo por un solo error.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'a1f2b7682afceff638f0756fa482e8bff869378549bbb3a2619915e03ce387f9'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Es buen profe pero lo que explica en clase se queda corto para lo que se necesita en el proyecto. Solo hay quices, tareas y el proyecto, que es muy rudo y largo. Pero si se le pide ayuda, responde aunque sea fin de semana o muy de noche.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2021-07-18T00:00:00+00:00'::TIMESTAMPTZ, '7e341dd94ffd83cbf9f64692789882b0588b60e656c2aa0bad04855abe9e3cf0'::TEXT, ARRAY[1216, 1241]::BIGINT[]),
    (597::BIGINT, 'Es buen profesor, pero algunas veces se enoja si tiene que repetir las instrucciones o la explicación varias veces. También cuando le pide ayuda no da mucha retroalimentación y lo deja con la misma duda. Pone bastantes tareas pero realmente ayudan para aprender si es que le cuesta.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '72edeb9df99e3fd310ecd7dbbad9c8f8384c6f3f7e12f921a6184692f0813808'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'El curso el profe lo hace como de unos 6 créditos, un proyecto del 50% del curso es gigante y hace grupos muy grandes y al final solo dos personas terminamos trabajando no da rúbricas de nada y califica como le da la gana, en otro 50 % del curso son quinces y tareas las cuales califica muy duro que'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-06-03T00:00:00+00:00'::TIMESTAMPTZ, '99d9699eddd5331daaaa6310af15a63a837acdec656a4ccab5e9441319cca865'::TEXT, ARRAY[1216, 1241]::BIGINT[]),
    (597::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2021-02-17T00:00:00+00:00'::TIMESTAMPTZ, '64f7079015d32c79cc31a104aea36f464b99dccd3e960423645d370e2898c063'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Muy desordenado con las notas usted nunca sabe si va bien o mal en el curso, las clases eran sumamente cansadas y largas y el receso de 10 min que daba había que usarlo para terminar el trabajo en clase y subirlo al tec digital ya que sino lo subía a la hora no daba más tiempo y perdía los puntos'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2020-09-08T00:00:00+00:00'::TIMESTAMPTZ, '238e8e93333f213d3c4c03ea15e1d2528a971249441f9c8356e8f458292dbe24'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Es un poco estricto al calificar pero nada fuera de lo común, se pasa fácil si se le mete ganas al curso'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2020-08-28T00:00:00+00:00'::TIMESTAMPTZ, 'bcfd9db88cdb85850dadf9a5d6fb2e1440fd609ba2527c03b0df2f0d7aa180de'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '55'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '63b6c892ac9efe86dfd48564161681894508b03d3bec8ea1eea06d439f6933d2'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Es demasiado irresponsable, luego de semanas de haber terminado el semestre no ha calificado más de la mitad de las asignaciones. El proyecto es sumamente extenso y tiene muy poca relación con lo visto en el curso. No queda de otra más que matricular con él, pero es un dolor de cabeza'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '131a2f2d5b6558ee8e76b885bdfa4b23cca6066295d926f24f21d43cc5231eba'::TEXT, ARRAY[1216, 1241]::BIGINT[]),
    (597::BIGINT, 'Es muy desordenado para dar notas al final del curso, porque se le acumulan las cosas. Para los exámenes da súper poco tiempo y en la parte de interpretación no hace práctica y califica súper rudo por cosas que no explicó.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'f02c2f018a6b28feae6d67fa3330ebc7003dcfadccbe4a25f3834be40c809a64'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'A la hora de los exámenes los hace súper rudos y da un tiempo poco prudencial para hacerlo. Siempre está de mal genio y es un poco altanero. No aclara dudas y si lo hace es de una mala forma. Explica súper mal y se le olvida grabar las clases. Lo llevé virtual.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, 'f2266d7d298e7bfbc944ca329068645d76da9d23b173defc696d988ee55f0146'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Buen profe para la modalidad virtual, se mantuvieron las clases por zoom y luego las subía a un drive. Casi todas las semanas hay tareas y si uno hace todo a conciencia se pasa fácil. Explica bastante bien y le gusta que uno aprenda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '8f84a0b1a66851e89588d6001efa216cc9d514d233c839f0c352d1f2bb1898b9'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'NO ME PARECIO PARA NADA BUENO, INICIA SUPER BIEN Y LUEGO ESTA DE MAL GENIO, NO ACEPTA QUE SE QUEDEN SIN INTERNET Y PARA LOS EXAMENES DA UNA HORA'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'ffbec58a31f75fa0c90cbbedee78841e35e03f73f52a9f3af95f130261b8daea'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Excelente profesor. Entendí en todo momento lo que explica. Brinda mucho apoyo cuando uno lo necesita. No deja tantas tareas, solo las necesarias. Súper recomendado'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '17b1ed6ebaa7d584aa48f7d007aa81d2fdf7bc439edc987249528f5c72c57290'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '0084424615c2715dcfaff46cb9e00512b9ed74fc7c1124179067d6c10670a2a9'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Muchas tareas, a la hora de evaluar los trabajos no es claro lo que puede estar bueno en un trabajo en otro puede estar mal... Eso sí está dispuesto a ayudar o a explicar de nuevo.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'f30d2b50219a10760606c484684f4cf980a633156545daa93c207388d7be38be'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'El profesor es muy confuso'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '01e3e568dcec5010d20a8e4539ecd51aee2a8dfcf927bb9519f66b4f30e9ed90'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'No explica algunos aspectos a evaluar de las tareas hasta después de entregarlas'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2019-05-28T00:00:00+00:00'::TIMESTAMPTZ, '887d537afcd71931ee3b1bbec5576b0dc7f5994ea81b0ba6b7241aa7e7b2aaeb'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Brinda apoyo']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'bbd44be24d9bdbbe10612601cc28f9f7967af8f0c7e2c26de1c9273b62965838'::TEXT, ARRAY[1216, 1241]::BIGINT[]),
    (597::BIGINT, 'Buen profesor. Sin emabargo es necesario poner muchisima atencion cuando da las clases. Muchas tareas, muchos trabajos, pero todo con el fin de que usted aprenda. Profesor al cual hay que tenerle mucho respeto.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Respetado por los estudiantes']::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'f7fef52f4aa62aeffdc0efd07a3014bcc4e502e104a137e9a5d1e4f3b2517a08'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'El profesor califica muy imparcial, además de que si uno le pide ayuda, depende de su humor te puede tratar bien o mal. Es muy bipolar. No le gusta cuando enseña en autocad pero sí le gusta planos.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Exámenes retadores']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '0f268b2f1757f2441c17419c23bc1f486f8b5a5d7b02d9d8e25a0c620771cb84'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '798b40a93f7770e4f345d71db183d2b7be0c30f138e7e026d5fc7c0263f29cb9'::TEXT, ARRAY[1216, 1241]::BIGINT[]),
    (597::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2018-04-24T00:00:00+00:00'::TIMESTAMPTZ, 'e997a5d259f2cf99b27953a7310035bfb68e08de3eb119a2f43dc9668b686201'::TEXT, ARRAY[1179]::BIGINT[]),
    (597::BIGINT, 'Es muy desordenado(a la hora de calificar), no acepta que se equivoca. Por lo otro, se trabaja mucho pero termina siendo un curso fácil si se tiene un buen grupo de trabajo'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '78ac0c36265ad6f34a43e71aeb5a90026ecc2bb7279612a57c1161d1162d6d2d'::TEXT, ARRAY[1216, 1241]::BIGINT[]),
    (597::BIGINT, 'Le encanta el curso, explica muy bien, clases aburridas, se trabaja demasiado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'La participación importa']::TEXT[], '2017-06-05T00:00:00+00:00'::TIMESTAMPTZ, '01af21660d4527c2d6ff93b094c30e67ff9d3c1b242d09913d15a41aff47763c'::TEXT, ARRAY[1216]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
